#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>

#define MAX_MEMTABLE_ENTRIES 1000
#define BLOOM_BITS 8192

typedef struct {
    uint8_t bits[BLOOM_BITS / 8];
} bloom_filter_t;

uint32_t hash_fnv1a(const char *key) {
    uint32_t hash = 2166136261u;
    while (*key) {
        hash ^= (uint8_t)*key++;
        hash *= 16777619u;
    }
    return hash;
}

uint32_t hash_murmur3(const char *key) {
    uint32_t h = 0x811c9dc5; 
    uint32_t c1 = 0xcc9e2d51;
    uint32_t c2 = 0x1b873593;
    int len = strlen(key);
    const uint8_t *data = (const uint8_t *)key;
    int nblocks = len / 4;
    for (int i = 0; i < nblocks; i++) {
        uint32_t k;
        memcpy(&k, data + i * 4, 4);
        k *= c1;
        k = (k << 15) | (k >> 17);
        k *= c2;
        h ^= k;
        h = (h << 13) | (h >> 19);
        h = h * 5 + 0xe6546b64;
    }
    const uint8_t *tail = data + nblocks * 4;
    uint32_t k1 = 0;
    if ((len & 3) >= 3) k1 ^= tail[2] << 16;
    if ((len & 3) >= 2) k1 ^= tail[1] << 8;
    if ((len & 3) >= 1) {
        k1 ^= tail[0];
        k1 *= c1;
        k1 = (k1 << 15) | (k1 >> 17);
        k1 *= c2;
        h ^= k1;
    }
    h ^= len;
    h ^= h >> 16;
    h *= 0x85ebca6b;
    h ^= h >> 13;
    h *= 0xc2b2ae35;
    h ^= h >> 16;
    return h;
}

void bloom_add(bloom_filter_t *filter, const char *key) {
    uint32_t h1 = hash_fnv1a(key);
    uint32_t h2 = hash_murmur3(key);
    for(int i=0; i<3; i++) { 
        uint32_t bit = (h1 + i * h2) % BLOOM_BITS;
        filter->bits[bit / 8] |= (1 << (bit % 8));
    }
}

bool bloom_check(const bloom_filter_t *filter, const char *key) {
    uint32_t h1 = hash_fnv1a(key);
    uint32_t h2 = hash_murmur3(key);
    for(int i=0; i<3; i++) {
        uint32_t bit = (h1 + i * h2) % BLOOM_BITS;
        if ((filter->bits[bit / 8] & (1 << (bit % 8))) == 0) {
            return false;
        }
    }
    return true;
}

typedef struct {
    char *key;
    char *val;
} kv_pair_t;

typedef struct {
    kv_pair_t entries[MAX_MEMTABLE_ENTRIES];
    int count;
} memtable_t;

typedef struct {
    kv_pair_t *entries;
    int count;
    bloom_filter_t bloom;
    int level;
} sstable_t;

memtable_t memtable;
sstable_t *sstables = NULL;
int num_sstables = 0;

void lsm_put(const char *key, const char *val);
bool lsm_get(const char *key, char *val_out);
void lsm_delete(const char *key);
void lsm_compact(void);

int find_memtable(const char *key, bool *found) {
    int L = 0, R = memtable.count - 1;
    while (L <= R) {
        int M = L + (R - L) / 2;
        int cmp = strcmp(memtable.entries[M].key, key);
        if (cmp == 0) {
            *found = true;
            return M;
        } else if (cmp < 0) {
            L = M + 1;
        } else {
            R = M - 1;
        }
    }
    *found = false;
    return L;
}

void flush_memtable(void) {
    if (memtable.count == 0) return;

    num_sstables++;
    sstables = realloc(sstables, num_sstables * sizeof(sstable_t));
    if (num_sstables > 1) {
        memmove(&sstables[1], &sstables[0], (num_sstables - 1) * sizeof(sstable_t));
    }
    sstable_t *new_sst = &sstables[0];

    new_sst->level = 0;
    new_sst->count = memtable.count;
    new_sst->entries = malloc(memtable.count * sizeof(kv_pair_t));
    memset(&new_sst->bloom, 0, sizeof(bloom_filter_t));

    for (int i = 0; i < memtable.count; i++) {
        new_sst->entries[i] = memtable.entries[i];
        bloom_add(&new_sst->bloom, new_sst->entries[i].key);
    }
    memtable.count = 0;

    int l0_count = 0;
    for (int i = 0; i < num_sstables; i++) {
        if (sstables[i].level == 0) l0_count++;
    }
    if (l0_count > 4) {
        lsm_compact();
    }
}

void lsm_put(const char *key, const char *val) {
    bool found;
    int idx = find_memtable(key, &found);
    if (found) {
        if (memtable.entries[idx].val) {
            free(memtable.entries[idx].val);
        }
        memtable.entries[idx].val = val ? strdup(val) : NULL;
    } else {
        if (memtable.count >= MAX_MEMTABLE_ENTRIES) {
            flush_memtable();
            idx = find_memtable(key, &found);
        }
        for (int i = memtable.count; i > idx; i--) {
            memtable.entries[i] = memtable.entries[i - 1];
        }
        memtable.entries[idx].key = strdup(key);
        memtable.entries[idx].val = val ? strdup(val) : NULL;
        memtable.count++;
    }
}

void lsm_delete(const char *key) {
    lsm_put(key, NULL);
}

int find_sstable(sstable_t *sst, const char *key) {
    int L = 0, R = sst->count - 1;
    while (L <= R) {
        int M = L + (R - L) / 2;
        int cmp = strcmp(sst->entries[M].key, key);
        if (cmp == 0) return M;
        else if (cmp < 0) L = M + 1;
        else R = M - 1;
    }
    return -1;
}

bool lsm_get(const char *key, char *val_out) {
    bool found;
    int idx = find_memtable(key, &found);
    if (found) {
        if (memtable.entries[idx].val == NULL) return false;
        strcpy(val_out, memtable.entries[idx].val);
        return true;
    }

    for (int i = 0; i < num_sstables; i++) {
        if (!bloom_check(&sstables[i].bloom, key)) continue;
        int s_idx = find_sstable(&sstables[i], key);
        if (s_idx >= 0) {
            if (sstables[i].entries[s_idx].val == NULL) return false;
            strcpy(val_out, sstables[i].entries[s_idx].val);
            return true;
        }
    }
    return false;
}

typedef struct {
    char *key;
    char *val;
    int age; 
} merge_item_t;

int merge_cmp(const void *a, const void *b) {
    const merge_item_t *ma = (const merge_item_t *)a;
    const merge_item_t *mb = (const merge_item_t *)b;
    int cmp = strcmp(ma->key, mb->key);
    if (cmp != 0) return cmp;
    return ma->age - mb->age;
}

void lsm_compact(void) {
    int total_entries = 0;
    for (int i = 0; i < num_sstables; i++) {
        total_entries += sstables[i].count;
    }
    if (total_entries == 0) return;

    merge_item_t *merged = malloc(total_entries * sizeof(merge_item_t));
    if (!merged) return;

    int idx = 0;
    for (int i = 0; i < num_sstables; i++) {
        for (int j = 0; j < sstables[i].count; j++) {
            merged[idx].key = sstables[i].entries[j].key;
            merged[idx].val = sstables[i].entries[j].val;
            merged[idx].age = i;
            idx++;
        }
    }

    qsort(merged, total_entries, sizeof(merge_item_t), merge_cmp);

    int unique = 0;
    for (int i = 0; i < total_entries; i++) {
        if (i == 0 || strcmp(merged[i].key, merged[i-1].key) != 0) {
            if (merged[i].val != NULL) {
                unique++;
            }
        }
    }

    sstable_t new_l1;
    new_l1.level = 1;
    new_l1.count = unique;
    if (unique > 0) {
        new_l1.entries = malloc(unique * sizeof(kv_pair_t));
    } else {
        new_l1.entries = NULL;
    }
    memset(&new_l1.bloom, 0, sizeof(bloom_filter_t));

    int out_idx = 0;
    for (int i = 0; i < total_entries; i++) {
        if (i == 0 || strcmp(merged[i].key, merged[i-1].key) != 0) {
            if (merged[i].val != NULL) {
                new_l1.entries[out_idx].key = strdup(merged[i].key);
                new_l1.entries[out_idx].val = strdup(merged[i].val);
                bloom_add(&new_l1.bloom, new_l1.entries[out_idx].key);
                out_idx++;
            }
        }
    }

    for (int i = 0; i < num_sstables; i++) {
        for (int j = 0; j < sstables[i].count; j++) {
            free(sstables[i].entries[j].key);
            if (sstables[i].entries[j].val) free(sstables[i].entries[j].val);
        }
        free(sstables[i].entries);
    }
    free(sstables);
    free(merged);

    if (unique > 0) {
        sstables = malloc(sizeof(sstable_t));
        sstables[0] = new_l1;
        num_sstables = 1;
    } else {
        sstables = NULL;
        num_sstables = 0;
    }
}

int main(void) {
    memtable.count = 0;

    for (int i = 0; i < 5000; i++) {
        char key[32], val[32];
        sprintf(key, "key%04d", i);
        sprintf(val, "val%04d", i);
        lsm_put(key, val);
    }

    for (int i = 0; i < 1000; i+=2) {
        char key[32];
        sprintf(key, "key%04d", i);
        lsm_delete(key);
    }

    int not_found_count = 0;
    for (int i = 5000; i < 15000; i++) {
        char key[32], val_out[32];
        sprintf(key, "key%04d", i);
        if (!lsm_get(key, val_out)) {
            not_found_count++;
        }
    }

    for (int i = 0; i < memtable.count; i++) {
        free(memtable.entries[i].key);
        if (memtable.entries[i].val) free(memtable.entries[i].val);
    }
    for (int i = 0; i < num_sstables; i++) {
        for (int j = 0; j < sstables[i].count; j++) {
            free(sstables[i].entries[j].key);
            if (sstables[i].entries[j].val) free(sstables[i].entries[j].val);
        }
        free(sstables[i].entries);
    }
    if (sstables) free(sstables);

    printf("FLAG: LSM-Tree Storage Engine Compaction Success!\n");
    return 0;
}
